export const MONSTER_TEXT_PT = { dict: DICT, spells: SPELL_NAMES_PT, nouns: CREATURE_NOUNS_PT, names: FEATURE_NAMES_PT };

/** Traduz o texto (desc.en) de um traço/ação; null se faltar alguma frase. */
export const translateMonsterText = createTranslator(MONSTER_TEXT_PT);

function localizeEntry(e) {
  if (!e || !e.name) return e;
  const out = { ...e };
  const en = e.name.en;
  if (en && FEATURE_NAMES_PT[en]) out.name = { ...e.name, pt: FEATURE_NAMES_PT[en] };
  if (e.desc && e.desc.en && !e.desc.pt) {
    const pt = translateMonsterText(e.desc.en);
    if (pt) out.desc = { ...e.desc, pt };
  }
  return out;
}

/** Devolve uma cópia do monstro com nomes e textos de traços/ações em pt-BR. */
export function localizeMonster(m) {
  if (!m) return m;
  const out = { ...m };
  for (const k of ['traits', 'actions', 'bonusActions', 'reactions']) {
    if (Array.isArray(m[k])) out[k] = m[k].map(localizeEntry);
  }
  if (m.legendary && Array.isArray(m.legendary.actions)) {
    out.legendary = { ...m.legendary, actions: m.legendary.actions.map(localizeEntry) };
  }
  return out;
}
